  device const half* t [[buffer(3)]], device float* loss [[buffer(4)]], constant uint& rows [[buffer(5)]],
  constant uint& cols [[buffer(6)]], constant float& lr [[buffer(7)]], uint i [[thread_position_in_grid]]) {
